contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmount)); require(depAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depAmount, "test contract must have enough ether for deposit");
        c.deposit{value: depAmount}(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;
        uint beforeThis = address(this).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert((reverted && address(c).balance == beforeBalance && address(this).balance == beforeThis) || (!reverted && address(c).balance + depAmount >= beforeBalance && address(c).balance <= beforeBalance));
    }

    receive() external payable {}
}

