// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depAmount) internal {
        depAmount = bound(depAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depAmount);
        try c.deposit{value: depAmount}() {} catch { return; }
        uint beforeBalance = address(c).balance;
        uint beforeThis = address(this).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assertTrue((reverted && address(c).balance == beforeBalance && address(this).balance == beforeThis) || (!reverted && address(c).balance + depAmount >= beforeBalance && address(c).balance <= beforeBalance));
    }

    function testFuzz_run(uint256 depAmount) public {
        _run(depAmount);
    }

    receive() external payable {}
}
